use kanpo_parser::{page_inputs,analyze_item};
const FORMULA:&str="各発行対象国債の額面金額×(各発行対象国債の利率/100)×(１/２)";
fn compact(s:&str)->String{s.chars().filter(|c|!c.is_whitespace()).collect()}
#[test] fn actual_parallel_20260812g001800016(){let a=analyze_item(&page_inputs(include_bytes!("archive/pages/20260812g00180/20260812g001800016.pdf")).unwrap());let cs:Vec<_>=a.pages.iter().flat_map(|p|&p.regions).flat_map(|r|&r.lines).filter_map(|l|l.table.as_ref()).flat_map(|t|&t.cells).filter(|c|compact(&c.text).contains(FORMULA)).collect();assert_eq!(cs.len(),1,"{}",a.text);assert_eq!((cs[0].row,cs[0].col),(10,1));assert_eq!(cs[0].words,vec![97, 98, 99, 100, 49, 32, 101, 40, 45, 33]);}
