#[test] fn unchanged_numeric_wrapped_22511(){let a=analyze_item(&page_inputs(include_bytes!("archive/pages/20261014g00225/20261014g002250011.pdf")).unwrap());let texts:Vec<_>=a.pages.iter().flat_map(|p|&p.regions).flat_map(|r|&r.lines).filter_map(|l|l.table.as_ref()).flat_map(|t|&t.cells).filter(|c|c.words!=vec![62,63,29,0,64,2,20,1]).map(|c|c.text.as_str()).collect();assert_eq!(texts,vec!["令和八年十月十四日","１名称及び記号","２　発行の根拠法律及びその条項","３　振替法の適用等","４発行額","５最低額面金額","６振替単位","７発行日","８発行価格","９　初期利子の適用利率","財務大臣　片山さつき","個人向け利付国庫債券（変動・10年）（第197回）","特別会計に関する法律（平成19年法律第23号）第46条第１項","社債、株式等の振替に関する法律（平成13年法律第75号。以下「振替法」という。）の規定の適用を受けるものとし、その振替機関は日本銀行とする。","額面金額で331,521,960,000円","10,000円","振替法の規定による振替口座簿の記載又は記録は、最低額面金額の整数倍の金額によるものとする。","令和８年９月15日","額面金額100円につき100円","年1.87％","12　第２期以後の利子","13　償還期限","14　償還金額","15　払込期日","16　払込場所","17　中途換金の取扱い","18　中途換金の特例","19　元利金支払場所","令和18年９月15日","額面金額100円につき100円","令和８年９月15日","日本銀行の本店又は支店","中途換金の買取りは、令和９年９月15日以後において行うこととし、その買取金額は、次の区分に応じ、それぞれの算式により算出した金額とする。\n（１）　令和９年９月15日から令和10年３月15日前までの間の場合\n額面金額＋経過利子に相当する金額−（初期利子に相当する金額×(79.685/100)＋第２期利子に相当する金額×(79.685/100)）\n（２）　令和10年３月15日以後の場合\n額面金額＋経過利子に相当する金額−（買い取る日の直前の利子支払期に支払われた利子に相当する金額×(79.685/100)＋その直前の利子支払期に\n支払われた利子に相当する金額×(79.685/100)）","前号による取扱いのほか、個人向け国債を有する者（相続税法（昭和25年法律第73号）第21条の４第１項に規定する特定障害者扶養信託契約の受益者及び所得税法等の一部を改正する法律（平成25年法律第５号）第３条の規定による改正前の相続税法第21条の４第１項に規定する特別障害者扶養信託契約の受益者を含む。）が、死亡したときにはその相続人が、又はその居住する市町村（特別区を含み、地方自治法（昭和22年法律第67号）第252条の19第１項の指定都市にあっては、当該市又は当該市の区若しくは総合区とする。）の区域において、災害救助法（昭和22年法律第118号）による救助の行われる災害が発生し、当該災害にかかったときには当該個人向け国債を有する者が、令和９年９月15日前であっても、当該個人向け国債の中途換金を請求することができるものとし、その買取金額は、次の区分に応じ、それぞれの算式により算出した金額とする。\n（１）　令和９年３月15日から令和９年９月15日前までの間の場合\n額面金額＋経過利子に相当する金額−（初期利子に相当する金額×(79.685/100)＋経過利子に相当する金額）\n（２）　令和９年３月15日前の場合\n額面金額＋経過利子に相当する金額−経過利子に相当する金額","日本銀行"]);}

#[test]fn discovered_actual_parallel22511(){let a=analyze_item(&page_inputs(include_bytes!("archive/pages/20261014g00225/20261014g002250011.pdf")).unwrap());let cs:Vec<_>=a.pages.iter().flat_map(|p|&p.regions).flat_map(|r|&r.lines).filter_map(|l|l.table.as_ref()).flat_map(|t|&t.cells).filter(|c|compact(&c.text).contains("額面金額×(第10号に規定する第２期以後の利子の適用利率/100)×(１/２)")).collect();assert_eq!(cs.len(),1);assert_eq!(cs[0].words,vec![62,63,29,0,64,2,20,1]);}
